-- Run once in Supabase Dashboard -> SQL Editor (after 002).
-- Adds 64 questions so every topic has at least 5 Easy, 5 Medium
-- and 5 Hard questions. Safe to run again: existing questions are skipped.

on conflict (question) do nothing;

notify pgrst, 'reload schema';

-- Check: questions per topic and difficulty
select topic, difficulty, count(*) as questions
from public.questions
group by topic, difficulty
order by topic, difficulty;
