insert into public.questions (question, options, correct_index, topic, difficulty)
values
  ('Processes P1, P2 and P3 arrive at time 0 with burst times 6, 8 and 3 ms. Using non-preemptive SJF, what is the average waiting time?', array['5.67 ms', '4 ms', '3 ms', '6 ms'], 1, 'CPU Scheduling', 'Hard'),
  ('P1 (burst 5 ms) and P2 (burst 3 ms) arrive at time 0 in that order. Using Round Robin with a 2 ms quantum, at what time does P2 finish?', array['8 ms', '5 ms', '7 ms', '6 ms'], 2, 'CPU Scheduling', 'Hard'),
  ('Using preemptive SJF (SRTF), P1 arrives at time 0 with a burst of 8 ms and P2 arrives at time 1 with a burst of 4 ms. When does P1 complete?', array['9 ms', '13 ms', '8 ms', '12 ms'], 3, 'CPU Scheduling', 'Hard'),
  ('In a multilevel feedback queue, what typically happens to a process that uses its entire time quantum?', array['It is moved to a lower-priority queue', 'It is moved to a higher-priority queue', 'It is terminated', 'It is moved to the waiting queue'], 0, 'CPU Scheduling', 'Hard'),
  ('In a resource-allocation graph where every resource has a single instance, what does a cycle indicate?', array['The system is in a safe state', 'A deadlock exists', 'A process has terminated', 'Starvation has occurred'], 1, 'Deadlocks', 'Medium'),
  ('Requiring a process to request all of its resources before it starts executing prevents which deadlock condition?', array['Mutual exclusion', 'Hold and wait', 'No preemption', 'Circular wait'], 1, 'Deadlocks', 'Medium'),
  ('Numbering all resource types and requiring processes to request them in increasing order prevents which deadlock condition?', array['Mutual exclusion', 'Hold and wait', 'No preemption', 'Circular wait'], 3, 'Deadlocks', 'Medium'),
  ('A system has 12 instances of one resource. P0 holds 5 (maximum 10), P1 holds 2 (maximum 4) and P2 holds 2 (maximum 9). Is the state safe?', array['Yes, safe sequence P0, P1, P2', 'No, the state is unsafe', 'Yes, safe sequence P1, P0, P2', 'Yes, safe sequence P2, P1, P0'], 2, 'Deadlocks', 'Hard'),
  ('Three processes each need at most 2 instances of a resource. What is the minimum number of instances that guarantees deadlock cannot occur?', array['3', '4', '5', '6'], 1, 'Deadlocks', 'Hard'),
  ('Why is an unsafe state not necessarily a deadlock?', array['Processes may release resources or never request their maximum, so deadlock can still be avoided', 'Unsafe states only apply to single-instance resources', 'The OS immediately preempts resources in unsafe states', 'Deadlock requires more than two processes'], 0, 'Deadlocks', 'Hard'),
  ('When every resource has a single instance, deadlock detection usually searches which graph for cycles?', array['Page table', 'Wait-for graph', 'Gantt chart', 'Process control block list'], 1, 'Deadlocks', 'Hard'),
  ('In Unix-like systems, what is an inode?', array['A structure that stores a file''s metadata', 'A type of directory', 'A running process', 'A disk partition'], 0, 'File Systems', 'Easy'),
  ('What does a file extension such as .txt or .jpg usually indicate?', array['The size of the file', 'The type of data the file contains', 'The owner of the file', 'The date the file was created'], 1, 'File Systems', 'Easy'),
  ('Which allocation method stores each file in one continuous run of disk blocks?', array['Linked allocation', 'Indexed allocation', 'Contiguous allocation', 'Paged allocation'], 2, 'File Systems', 'Medium'),
  ('What is a major drawback of contiguous file allocation?', array['External fragmentation and difficulty growing files', 'Slow sequential access', 'Each block needs a pointer to the next', 'It cannot store directories'], 0, 'File Systems', 'Medium'),
  ('In linked allocation, how is the next block of a file found?', array['From an index block', 'Each block contains a pointer to the next block', 'Blocks are always next to each other', 'From the page table'], 1, 'File Systems', 'Medium'),
  ('What is the difference between an absolute path and a relative path?', array['An absolute path starts from the root directory; a relative path starts from the current directory', 'An absolute path is always shorter', 'A relative path can only point to files, not directories', 'There is no difference'], 0, 'File Systems', 'Medium'),
  ('In Unix-like systems, what does creating a hard link to a file do?', array['Copies the file''s data', 'Adds another directory entry that points to the same inode', 'Creates a shortcut that stores the file''s path', 'Locks the file for writing'], 1, 'File Systems', 'Medium'),
  ('A file system uses 4 KB blocks and an index block holds 1024 block pointers. With a single index block, what is the maximum file size?', array['1 MB', '4 MB', '16 MB', '4 GB'], 1, 'File Systems', 'Hard'),
  ('Why is random (direct) access slow with linked allocation?', array['Reaching block n requires following n pointers from the start of the file', 'Linked blocks cannot be cached', 'Each block must be decrypted first', 'The directory must be rebuilt for every read'], 0, 'File Systems', 'Hard'),
  ('A file system uses 4 KB blocks. How many blocks does a 10 KB file occupy, and how much space is unused in its last block?', array['2 blocks, 2 KB unused', '3 blocks, 0 KB unused', '3 blocks, 2 KB unused', '2 blocks, 0 KB unused'], 2, 'File Systems', 'Hard'),
  ('A file has two hard links. What happens to its data when one of the links is deleted?', array['The data is deleted immediately', 'The data remains because the other link still refers to the inode', 'The remaining link becomes a symbolic link', 'The file becomes read-only'], 1, 'File Systems', 'Hard'),
  ('Why do journaling file systems recover faster after a crash?', array['They replay or discard a log of pending changes instead of checking the whole disk', 'They store every file twice', 'They never write metadata to disk', 'They disable caching'], 0, 'File Systems', 'Hard'),
  ('What is the main difference between a hard link and a symbolic (soft) link?', array['A symbolic link stores a path to the target, so it breaks if the target is removed', 'A hard link can point to a file on another disk', 'A symbolic link copies the file''s data', 'A hard link stores the file''s path as text'], 0, 'File Systems', 'Hard'),
  ('What is the purpose of a Translation Lookaside Buffer (TLB)?', array['To store swapped-out pages', 'To cache recent page-table translations and speed up address translation', 'To hold the ready queue', 'To store file metadata'], 1, 'Memory Management', 'Medium'),
  ('What is thrashing?', array['The system spends most of its time swapping pages instead of executing processes', 'A process writing to another process''s memory', 'Fragmentation inside a page', 'A CPU running at full speed'], 0, 'Memory Management', 'Medium'),
  ('A system uses 32-bit logical addresses and 4 KB pages. How many entries does a single-level page table have?', array['2^12 (4,096)', '2^20 (1,048,576)', '2^32', '2^10 (1,024)'], 1, 'Memory Management', 'Hard'),
  ('Using FIFO page replacement with 3 frames (initially empty), how many page faults occur for the reference string 1, 2, 3, 4, 1, 2?', array['4', '5', '6', '3'], 2, 'Memory Management', 'Hard'),
  ('Using LRU page replacement with 3 frames (initially empty), how many page faults occur for the reference string 1, 2, 3, 1, 4, 2?', array['4', '6', '3', '5'], 3, 'Memory Management', 'Hard'),
  ('What is Belady''s anomaly?', array['Giving a process more frames causes more page faults under FIFO', 'LRU always performs worse than FIFO', 'Page faults stop once memory is full', 'Larger pages always cause fewer faults'], 0, 'Memory Management', 'Hard'),
  ('What is the main difference between a program and a process?', array['A program is passive code stored on disk; a process is a program in execution', 'A process is stored on disk; a program runs in memory', 'They are the same thing', 'A program can only run once'], 0, 'OS Basics', 'Medium'),
  ('What is the difference between multiprogramming and multiprocessing?', array['Multiprogramming keeps several programs in memory for one CPU; multiprocessing uses more than one CPU', 'Multiprocessing runs only one program at a time', 'Multiprogramming requires several CPUs', 'There is no difference'], 0, 'OS Basics', 'Medium'),
  ('What is the purpose of a timer interrupt in a multitasking operating system?', array['It lets the OS regain control of the CPU so one process cannot run forever', 'It keeps the system clock accurate for users', 'It speeds up disk access', 'It prevents page faults'], 0, 'OS Basics', 'Hard'),
  ('How does a monolithic kernel differ from a microkernel?', array['A monolithic kernel runs most OS services in kernel space; a microkernel moves many of them to user space', 'A microkernel is always larger', 'A monolithic kernel has no system calls', 'A microkernel cannot run device drivers'], 0, 'OS Basics', 'Hard'),
  ('Which of these switches the CPU from user mode to kernel mode?', array['Calling a library function like strlen()', 'Declaring a local variable', 'A system call, interrupt or exception', 'Opening a text editor window'], 2, 'OS Basics', 'Hard'),
  ('Why is the instruction that disables interrupts a privileged instruction?', array['A user program could otherwise stop the OS from ever regaining control', 'It is too slow for user programs', 'It needs more memory than user mode allows', 'It only works on multiprocessor systems'], 0, 'OS Basics', 'Hard'),
  ('Which of the following is an example of a graphical user interface (GUI)?', array['A Bash terminal', 'A desktop with windows, icons and a mouse pointer', 'A system call', 'The BIOS setup screen'], 1, 'OS Interface', 'Easy'),
  ('In a Linux shell, which command lists the files in the current directory?', array['cd', 'ls', 'pwd', 'mkdir'], 1, 'OS Interface', 'Easy'),
  ('In a Linux shell, which command shows the current working directory?', array['pwd', 'ls', 'cd', 'echo'], 0, 'OS Interface', 'Easy'),
  ('In the shell command ls | grep txt, what does the pipe operator (|) do?', array['Runs both commands at the same time without connecting them', 'Sends the output of the first command as input to the second', 'Saves the output to a file called grep', 'Runs grep only if ls fails'], 1, 'OS Interface', 'Medium'),
  ('In the shell command echo hi > file.txt, what does > do?', array['Appends the output to file.txt', 'Redirects the output into file.txt, replacing its contents', 'Reads input from file.txt', 'Compares the output with file.txt'], 1, 'OS Interface', 'Medium'),
  ('In an operating system, what is an API such as POSIX or the Win32 API?', array['A set of functions programs use to request OS services', 'A type of file system', 'A hardware device driver', 'A scheduling algorithm'], 0, 'OS Interface', 'Medium'),
  ('Why do programs usually call library functions like printf() instead of making system calls directly?', array['Libraries give a simpler, portable interface and make the system calls for them', 'System calls are not allowed in C', 'Library functions never use the kernel', 'System calls only work in a GUI'], 0, 'OS Interface', 'Medium'),
  ('What is the PATH environment variable used for?', array['Storing the user''s password', 'Telling the shell which directories to search for commands', 'Setting the screen resolution', 'Recording the shell''s command history'], 1, 'OS Interface', 'Medium'),
  ('When you type a command like ls into a shell, what does the shell typically do?', array['It calls fork() to create a child, which calls exec() to run ls while the shell waits', 'It runs ls inside its own process without creating a new one', 'It sends the command to the BIOS', 'It restarts itself as ls'], 0, 'OS Interface', 'Hard'),
  ('Why must the cd command be built into the shell instead of being a separate program?', array['A child process cannot change its parent''s current directory', 'cd needs kernel mode', 'Separate programs cannot read directories', 'cd is too small to be a program'], 0, 'OS Interface', 'Hard'),
  ('What happens when a command is run with & at the end, such as sleep 10 &?', array['The command runs twice', 'The shell starts it in the background and returns to the prompt immediately', 'The command''s output is hidden', 'The command runs with administrator rights'], 1, 'OS Interface', 'Hard'),
  ('In the command gcc main.c 2> errors.txt, what does 2> do?', array['Runs gcc twice', 'Redirects standard output to errors.txt', 'Redirects standard error to errors.txt', 'Reads input from errors.txt'], 2, 'OS Interface', 'Hard'),
  ('What is the difference between a binary semaphore and a counting semaphore?', array['A counting semaphore can go above 1, so it can manage several units of a resource', 'A binary semaphore can be negative', 'A counting semaphore cannot block processes', 'There is no difference'], 0, 'Process Synchronization', 'Medium'),
  ('What is busy waiting?', array['A process repeatedly checks a condition in a loop, wasting CPU time', 'A process sleeping until it is woken up', 'A process waiting for disk I/O', 'Two processes sharing a CPU'], 0, 'Process Synchronization', 'Medium'),
  ('A counting semaphore starts at 3. Five processes each call wait() on it and none call signal(). How many processes are blocked?', array['0', '2', '3', '5'], 1, 'Process Synchronization', 'Hard'),
  ('In the bounded-buffer producer-consumer solution, what are the semaphores empty and full usually initialised to?', array['empty = 0, full = buffer size', 'empty = buffer size, full = 0', 'both = 1', 'both = 0'], 1, 'Process Synchronization', 'Hard'),
  ('Two threads each run counter++ 1000 times on a shared counter starting at 0, with no synchronisation. What can the final value be?', array['Always exactly 2000', 'Always exactly 1000', 'Possibly less than 2000, because increments can be lost', 'Always more than 2000'], 2, 'Process Synchronization', 'Hard'),
  ('Which three requirements must a correct critical-section solution satisfy?', array['Mutual exclusion, progress and bounded waiting', 'Speed, fairness and priority', 'Deadlock, starvation and aging', 'Preemption, paging and caching'], 0, 'Process Synchronization', 'Hard'),
  ('In the dining philosophers problem, why can ''pick up the left fork, then the right fork'' cause deadlock?', array['If every philosopher picks up their left fork at once, each waits forever for the right one', 'Forks can only be used once', 'Philosophers eat too quickly', 'The right fork is always faster to pick up'], 0, 'Process Synchronization', 'Hard'),
  ('What advantage does a monitor have over using semaphores directly?', array['Mutual exclusion is automatic, which avoids mistakes like a forgotten signal()', 'Monitors never block processes', 'Monitors work without shared memory', 'Monitors are always faster'], 0, 'Process Synchronization', 'Hard'),
  ('Which data structure does the OS use to store information about each process?', array['Page table', 'Process Control Block (PCB)', 'File allocation table', 'Ready queue'], 1, 'Processes & System Calls', 'Easy'),
  ('Which process state means a process is ready to run and waiting for the CPU?', array['Ready', 'Running', 'Waiting', 'Terminated'], 0, 'Processes & System Calls', 'Easy'),
  ('Which system call replaces the current process''s program with a new program?', array['fork()', 'exec()', 'wait()', 'exit()'], 1, 'Processes & System Calls', 'Easy'),
  ('Including the original process, how many processes exist after a program runs fork(); fork(); (with no errors)?', array['2', '3', '4', '8'], 2, 'Processes & System Calls', 'Hard'),
  ('After a successful fork(), what does fork() return in the parent and in the child?', array['The child''s PID in the parent, and 0 in the child', '0 in the parent, and the parent''s PID in the child', '1 in both', '-1 in the child'], 0, 'Processes & System Calls', 'Hard'),
  ('Why are threads cheaper to create than processes?', array['Threads share their process''s address space and resources, so less must be set up', 'Threads run in kernel mode', 'Threads do not need a CPU', 'Threads have no stack'], 0, 'Processes & System Calls', 'Hard'),
  ('A running process calls read() to get data from disk. Which state does it usually move to?', array['Ready', 'Waiting (blocked)', 'Terminated', 'New'], 1, 'Processes & System Calls', 'Hard'),
